<script setup>
import { onMounted, ref } from 'vue';import { listBills,confirmBill,payBill } from '../../../api/billing';import { session } from '../../../utils/session';import { money,text,tagType } from '../../../utils/enums';import { ElMessage,ElMessageBox } from 'element-plus'
const props=defineProps({caseId:Number});const list=ref([]);const path=session.user.role==='CLIENT'?'/client/bills':'/admin/bills';const load=async()=>list.value=(await listBills(path,{caseId:props.caseId,pageSize:100})).data.list
const confirm=async(id)=>{await confirmBill(id);ElMessage.success('账单已确认');load()};const pay=async(id)=>{await ElMessageBox.confirm('这是课程演示的模拟支付，确认支付？','模拟支付');await payBill(id);ElMessage.success('模拟支付成功');load()};onMounted(load)
</script>
<template><section class="tab-panel"><el-table :data="list"><el-table-column prop="billNo" label="账单编号" min-width="180"/><el-table-column prop="feeItem" label="费用项目"/><el-table-column label="应付金额" width="120"><template #default="{row}">{{money(row.payableAmount)}}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="tagType(row.status)">{{text('billStatus',row.status)}}</el-tag></template></el-table-column><el-table-column v-if="session.user.role==='CLIENT'" label="操作" width="130"><template #default="{row}"><el-button v-if="row.status==='PENDING_CONFIRM'" link type="primary" @click="confirm(row.id)">确认</el-button><el-button v-if="row.status==='PENDING_PAYMENT'" link type="success" @click="pay(row.id)">模拟支付</el-button></template></el-table-column></el-table></section></template>
